import { Order } from './types';
const cmp = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);
export class OrderRepository {
  constructor(private readonly rows: Order[]) {}
  list(tenant: string, after?: { createdAt: string; id: string }, max?: number): Order[] {
    const out = this.rows
      .filter(row => row.tenant === tenant)
      .filter(row => !after || cmp(row.createdAt, after.createdAt) > 0 ||
        (row.createdAt === after.createdAt && cmp(row.id, after.id) > 0))
      .sort((a, b) => cmp(a.createdAt, b.createdAt) || cmp(a.id, b.id));
    return max === undefined ? out : out.slice(0, max);
  }
}
EOF
cat > src/handler.ts <<'EOF'
import { OrderRepository } from './repository';
import { ListRequest, Page } from './types';
export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}
  list(request: ListRequest): Page {
    const { tenant, limit, cursor } = request;
    if (typeof tenant !== 'string' || !tenant || !Number.isInteger(limit) || limit < 1 || limit > 100) {
      throw new Error('invalid request');
    }
    let after: { createdAt: string; id: string } | undefined;
    if (cursor !== undefined) {
      const parts = typeof cursor === 'string' ? cursor.split('|') : [];
      if (parts.length !== 2 || !parts[0] || !parts[1]) throw new Error('invalid request');
      after = { createdAt: parts[0], id: parts[1] };
    }
    const found = this.repository.list(tenant, after, limit + 1);
    const items = found.slice(0, limit);
    const last = items[items.length - 1];
    return {
      items,
      nextCursor: found.length > limit && last ? last.createdAt + '|' + last.id : null,
    };
  }
}
EOF
cat >> checks/public.cjs <<'EOF'

const rows = [
  { id: 'b', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'a', tenant: 'a', createdAt: '2026-01-01', total: 1 },
  { id: 'c', tenant: 'a', createdAt: '2026-01-02', total: 1 },
  { id: 'z', tenant: 'b', createdAt: '2026-01-01', total: 1 }
];
const h2 = new OrderHandler(new OrderRepository(rows));
const p1 = h2.list({ tenant: 'a', limit: 1 });
assert.deepEqual([p1.items[0].id, p1.nextCursor], ['a', '2026-01-01|a']);
const p2 = h2.list({ tenant: 'a', limit: 1, cursor: p1.nextCursor });
assert.deepEqual([p2.items[0].id, p2.nextCursor], ['b', '2026-01-01|b']);
const p3 = h2.list({ tenant: 'a', limit: 5, cursor: '2026-01-01|b' });
assert.deepEqual([p3.items.map(x => x.id), p3.nextCursor], [['c'], null]);
assert.deepEqual(h2.list({ tenant: 'a', limit: 5, cursor: '2026-01-01|bb' }).items.map(x => x.id), ['c']);
assert.deepEqual(h2.list({ tenant: 'a', limit: 5, cursor: '2026-01-01|z' }).items.map(x => x.id), ['c']);
for (const cursor of ['', 'x', 'a|', '|a', 'a|b|c'])
  assert.throws(() => h2.list({ tenant: 'a', limit: 1, cursor }), /invalid request/);
assert.throws(() => h2.list({ tenant: '', limit: 1 }), /invalid request/);
assert.equal(rows[0].id, 'b');
EOF
